import sys; from PyQt5.QtWidgets import QApplication, QMainWindow; from PyQt5.QtWebEngineWidgets import QWebEngineView; from PyQt5.QtCore import Qt; app = QApplication(sys.argv); w = QMainWindow(); w.setWindowFlags(Qt.FramelessWindowHint | Qt.Window); w.setAttribute(Qt.WA_TranslucentBackground, True); web = QWebEngineView(w); web.setStyleSheet('background: transparent;'); web.page().setBackgroundColor(Qt.transparent); w.setCentralWidget(web); w.resize(800, 600); w.show(); sys.exit(app.exec_())
